def get_benchmark(platform):
    return CIS_BENCHMARKS.get(platform, [])

def get_all_checks():
    total = []
    for platform, checks in CIS_BENCHMARKS.items():
        for c in checks:
            total.append({**c, "platform": platform})
    return total

def get_stats():
    return {platform: len(checks) for platform, checks in CIS_BENCHMARKS.items()}

if __name__ == "__main__":
    stats = get_stats()
    total = sum(stats.values())
    print(f"AEGIS CIS Benchmarks: {total} checks across {len(stats)} platforms")
    for platform, count in stats.items():
        print(f"  {platform}: {count} checks")
